#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    long long maximumScore(vector<int>& a,int k){
        const long long NEG=LLONG_MIN/4;int n=a.size(),M=min(n,2*k);
        long long answer=0;
        for(int offset=0;offset<=2;offset++){
            vector<array<long long,3>>dp(M+1),ndp(M+1);
            for(auto &v:dp)v.fill(NEG);dp[0][offset]=0;
            for(int x:a){
                ndp=dp;
                for(int j=0;j<M;j++)for(int b=0;b<=2;b++)if(dp[j][b]!=NEG){
                    if(b<2)ndp[j+1][b+1]=max(ndp[j+1][b+1],dp[j][b]+x);
                    if(b>0)ndp[j+1][b-1]=max(ndp[j+1][b-1],dp[j][b]-x);
                }
                dp.swap(ndp);
            }
            for(int j=0;j<=M;j+=2)answer=max(answer,dp[j][offset]);
        }
        return answer;
    }
};
